import React from "react";
import TerrainForm from "./components/TerrainForm";
import ProjetForm from "./components/ProjetForm";
import EmployeForm from "./components/EmployeForm";
import Dashboard from "./components/Dashboard";

export default function App() {
    return (
        <div className="min-h-screen bg-gray-100">
            <header className="bg-blue-900 text-white p-4 shadow">
                <h1 className="text-2xl font-bold">AGEP – Gestion des Projets BTP</h1>
            </header>

            <main className="p-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="space-y-6">
                    <TerrainForm />
                    <ProjetForm />
                    <EmployeForm />
                </div>
                <div className="lg:col-span-2">
                    <Dashboard />
                </div>
            </main>
        </div>
    );
}
